bind('threshold',()=>{const c=current();if(!c)return;const low=prompt('Lower intensity threshold:',String(+$('level').value-10));if(low===null)return;const high=prompt('Upper intensity threshold:',String(+$('level').value+10));if(high===null)return;C.check(Number.isFinite(+low)&&Number.isFinite(+high)&&+low<=+high,'Enter valid threshold bounds');const p=C.plane(c.dims,axis,k),out=[];for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++){const i=p.index(x,y);if(c.data[i]>=+low&&c.data[i]<=+high)out.push(i)}suggest(out,'Local intensity threshold')});
