function reviewErrors(c){const e=[];if(project.targetsConfirmed!==true)e.push('Confirm label definitions in Project settings');if(checks.some((_,i)=>!c.checklist[i]))e.push('Complete all 10 acquisition checks');if(!c.selfReview)e.push('Complete self-review');if(!c.group.trim())e.push('Set a subject group ID');if(project.classFields.some(f=>!f.allowed.includes(c.classification[f.name])))e.push('Fill all classification fields');if(project.landmarkDefinitions.some(n=>!c.landmarks.some(l=>l.name===n)))e.push('Place all defined landmarks');if(!c.negative&&!c.mask.some(x=>x>0))e.push('Create a mask or confirm a negative case');if(c.negative&&c.mask.some(x=>x>0))e.push('Negative case cannot contain a mask');return e}
