async function ungzip(buf){return new Response(new Blob([buf]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()}
async function importFiles(files){C.check(restoreDone,'Please wait for the saved project to open');let groups=Object.create(null),errors=[],count=0;message('Reading images locally…');for(const f of files){if(f.name.startsWith('.'))continue;try{C.check(f.size<600*1024*1024,'File exceeds the 600 MB import limit');let buf=await f.arrayBuffer();if(/\.ioss$/i.test(f.name)){const volume=MedIoss.read(buf);volume.privateIdentity.source=f.medOriginalPath||f.webkitRelativePath||f.name;delete volume.instance;add(volume,f.name);count++}else if(/\.nii(\.gz)?$/i.test(f.name)){if(/\.gz$/i.test(f.name))buf=await ungzip(buf);add(C.nifti(buf),f.name);count++}else if(/\.(png|jpg|jpeg)$/i.test(f.name)){const bitmap=await createImageBitmap(f),can=document.createElement('canvas');C.size([bitmap.width,bitmap.height,1]);can.width=bitmap.width;can.height=bitmap.height;const cc=can.getContext('2d');cc.drawImage(bitmap,0,0);const raw=cc.getImageData(0,0,can.width,can.height).data,data=new Float32Array(can.width*can.height);for(let i=0;i<data.length;i++)data[i]=.299*raw[i*4]+.587*raw[i*4+1]+.114*raw[i*4+2];add({dims:[can.width,can.height,1],data,affine:C.identity(),geometry:'unknown',modality:'2D image',sequence:'Not supplied'},f.name);count++;bitmap.close()}else{const d=C.dicom(buf);d.privateIdentity.source=f.medOriginalPath||f.webkitRelativePath||f.name;if(d.projection){add(C.projectionImage(d),f.name);count++}else{const group=JSON.stringify([d.privateIdentity.patientId,d.privateIdentity.issuer,d.privateIdentity.studyUID,d.series,d.modality]);(groups[group]??=[]).push(d)}}}catch(e){errors.push(f.name+': '+e.message)}}for(const [uid,slices] of Object.entries(groups)){try{add(C.stack(slices),'DICOM series '+(project.cases.length+1));count++}catch(e){errors.push('Series: '+e.message)}}if(count)select(project.cases.length-1);message(`Imported ${count} volume(s).${errors.length?'\nSkipped '+errors.length+' input(s):\n'+errors.slice(0,8).join('\n'):''}`,!!errors.length);changed()}
bind('import',()=>$('files').click());bind('folder',()=>$('folders').click());$('files').onchange=safe(async e=>{await importFiles([...e.target.files]);e.target.value=''});$('folders').onchange=safe(async e=>{await importFiles([...e.target.files]);e.target.value=''});
function demo(){C.check(restoreDone,'Please wait for the saved project to open');const dims=[128,128,64],data=new Float32Array(C.size(dims));for(let z=0;z<64;z++)for(let y=0;y<128;y++)for(let x=0;x<128;x++){const head=((x-64)/49)**2+((y-64)/56)**2+((z-32)/28)**2,lesion=((x-77)/13)**2+((y-59)/16)**2+((z-34)/12)**2;data[x+128*(y+128*z)]=head<1?65+20*Math.sin(x*.12)*Math.cos(y*.1)+15*Math.sin(z*.15)+(lesion<1?110:0):0}add({dims,data,affine:[[1,0,0,-64],[0,1,0,-64],[0,0,2,-64],[0,0,0,1]],geometry:'synthetic RAS',modality:'SYNTHETIC',sequence:'Practice only'},'Synthetic practice volume');project.cases.at(-1).synthetic=true;select(project.cases.length-1);message('Synthetic practice volume loaded. Practice cases are excluded from training exports.')}
