function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function serializeProject(){const files={},metadata={...project,cases:project.cases.map(c=>{const {data,mask,...meta}=c;files[`images/${c.id}.nii`]=C.writeNifti(c);files[`masks/${c.id}.nii`]=C.writeNifti(c,mask,true);return meta})};files['project.json']=JSON.stringify(metadata,null,2);return C.zip(files)}
bind('save',()=>{download(serializeProject(),'MedAnnotate-project.medannotate');message('Project backup downloaded. Keep it in your approved local folder or Google Drive.');persist()});bind('open',()=>$('projectFile').click());bind('newProject',()=>{if(!confirm('Start a fresh workspace? Download a backup first to keep existing images and annotations.'))return;project.cases=[];project.projectKey=crypto.randomUUID().replace(/-/g,'').slice(0,8).toUpperCase();select(-1);changed();message('New empty workspace. Your label settings were retained.')});
function validateProject(p){C.check(p.version===1&&Array.isArray(p.cases)&&Array.isArray(p.labels),'Invalid project format');validateSettings(p);const ids=new Set();for(const c of p.cases){C.check(/^(?:CASE_[0-9]+|ECAR_[A-F0-9]{8}_[0-9]{6})$/.test(c.id)&&!ids.has(c.id),'Invalid or duplicate case ID');ids.add(c.id);C.check(typeof c.group==='string'&&Array.isArray(c.landmarks)&&c.checklist&&c.classification,'Missing case metadata');C.size(c.dims)}}
$('projectFile').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;if(project.cases.length&&!confirm('Replace this workspace? Save a project backup first to keep the current cases.'))return;const files=C.unzip(await f.arrayBuffer()),p=JSON.parse(new TextDecoder().decode(files['project.json']));validateProject(p);for(const c of p.cases){C.check(files[`images/${c.id}.nii`]&&files[`masks/${c.id}.nii`],'Missing image or mask');const img=C.nifti(files[`images/${c.id}.nii`].buffer),mask=C.nifti(files[`masks/${c.id}.nii`].buffer);C.check(img.dims.every((x,i)=>x===c.dims[i]&&x===mask.dims[i]),'Mask shape mismatch');C.check(mask.data.every(x=>x===0||p.labels.some(l=>l.value===x)),'Unknown mask label');c.data=img.data;c.mask=Uint16Array.from(mask.data)}project=p;label=p.labels[0].value;select(p.cases.length?0:-1);changed();message('Project restored, including images, masks and review metadata.');e.target.value=''});
function validateSettings(p){C.check(!p.projectKey||/^[A-F0-9]{8}$/.test(p.projectKey),'Project key must be 8 uppercase hexadecimal characters');C.check(typeof p.name==='string'&&p.name.trim(),'Project name required');C.check(Array.isArray(p.labels)&&p.labels.length>0&&p.labels.length<=99,'Define 1–99 labels');const ids=new Set();for(const l of p.labels){C.check(Number.isInteger(l.value)&&l.value>0&&l.value<=65535&&!ids.has(l.value)&&typeof l.name==='string'&&l.name.trim()&&/^#[0-9a-fA-F]{6}$/.test(l.color),'Each label needs a unique positive integer, name and #RRGGBB color');ids.add(l.value)}C.check(Array.isArray(p.classFields)&&p.classFields.every(f=>typeof f.name==='string'&&f.name.trim()&&Array.isArray(f.allowed)&&f.allowed.length&&f.allowed.every(a=>typeof a==='string')),'Invalid classification fields');C.check(new Set(p.classFields.map(f=>f.name)).size===p.classFields.length,'Duplicate classification fields');C.check(Array.isArray(p.landmarkDefinitions)&&p.landmarkDefinitions.every(x=>typeof x==='string'),'Landmarks must be an array of names')}
bind('settings',()=>{const {cases,...config}=project;modal(`<h2>Project settings</h2><p>Replace the protocol placeholders with agreed structure names and boundary definitions. Set <b>targetsConfirmed</b> to true only after agreeing these definitions with your reviewer.</p><textarea id="config" rows="19">${esc(JSON.stringify(config,null,2))}</textarea><p class="hint">Add boundary rules to each label as a “definition” string. Add expected checklist values to “protocol” using the checklist names as keys.</p><button id="applySettings" class="primary wide">Apply settings</button>`);bind('applySettings',()=>{const config=JSON.parse($('config').value);validateSettings(config);for(const c of project.cases)C.check(c.mask.every(x=>x===0||config.labels.some(l=>l.value===x)),'Cannot remove a label used in a mask');project={...config,version:1,cases:project.cases};project.cases.forEach(c=>{invalidate(c);c.selfReview=false});label=project.labels[0].value;changed();renderAll();$('dialog').close()})});
const csvCell=x=>'"'+String(x??'').replace(/"/g,'""')+'"',csv=rows=>rows.map(r=>r.map(csvCell).join(',')).join('\r\n');
bind('export',()=>{const eligible=project.cases.filter(c=>c.status==='reviewed'&&!c.synthetic&&!reviewErrors(c).length);modal(`<h2>Build training dataset</h2><p><b>${eligible.length}</b> reviewed research cases ready. Draft, flagged, incomplete and synthetic cases are excluded.</p><div class="info-box">Splits are grouped by your subject IDs. Assign the same ID to every series from one person. Tiny datasets may have empty validation or test splits.</div><div class="control-grid"><label>Training %<input id="trainPct" type="number" min="0" max="100" value="70"></label><label>Validation %<input id="valPct" type="number" min="0" max="100" value="15"></label></div><label>Random seed<input id="seed" value="2026"></label><p class="hint">Test receives the remaining percentage. Output includes NIfTI images and masks, dataset.json, splits_final.json, CSV tables, bounding boxes, Slicer landmarks, and provenance. Series remain separate single-channel cases.</p><label class="check"><input id="idsConfirmed" type="checkbox">I verified subject groups, image de-identification and permission to use these data.</label><button id="buildDataset" class="primary wide">Download dataset ZIP</button>`);bind('buildDataset',async()=>{C.check(eligible.length,'Review at least one real case before exporting');C.check($('idsConfirmed').checked,'Confirm subject grouping and data handling first');const train=+$('trainPct').value/100,val=+$('valPct').value/100,seed=$('seed').value;C.check(train>0&&Number.isFinite(train)&&Number.isFinite(val),'Training percentage must be positive');const split=C.splitGroups(eligible,seed,train,val),files={},classification=[['case_id','subject_group','split',...project.classFields.map(f=>f.name)]],tracking=[['case_id','status','included','reason']],boxes={},provenance={},trainIds=[],validationIds=[],testIds=[];message('Preparing dataset ZIP locally…');await new Promise(r=>setTimeout(r,20));for(const c of eligible){const test=split[c.id]==='test',folder=test?'Ts':'Tr';files[`segmentation/images${folder}/${c.id}_0000.nii.gz`]=await gzip(C.writeNifti(c));files[`segmentation/labels${folder}/${c.id}.nii.gz`]=await gzip(C.writeNifti(c,c.mask,true));(test?testIds:split[c.id]==='validation'?validationIds:trainIds).push(c.id);classification.push([c.id,c.group,split[c.id],...project.classFields.map(f=>c.classification[f.name])]);boxes[c.id]=Object.fromEntries(project.labels.map(l=>[l.value,C.bbox(c,l.value)]));provenance[c.id]={history:c.history,reviewedAt:c.reviewedAt,checklist:c.checklist,selfReview:c.selfReview,negative:c.negative,affine_RAS:c.affine,geometry:c.geometry,group:c.group};files[`landmarks/${c.id}.mrk.json`]=JSON.stringify({markups:[{type:'Fiducial',coordinateSystem:'LPS',coordinateUnits:'mm',locked:false,labelFormat:'%N-%d',controlPoints:c.landmarks.map((l,i)=>{const ras=c.affine.slice(0,3).map(row=>row[3]+row.slice(0,3).reduce((s,v,j)=>s+v*l.ijk[j],0));return {id:String(i+1),label:l.name,position:[-ras[0],-ras[1],ras[2]],orientation:[1,0,0,0,1,0,0,0,1],selected:true,locked:false,visibility:true,positionStatus:'defined'}})}]},null,2)}for(const c of project.cases)tracking.push([c.id,c.status,eligible.includes(c)?'yes':'no',c.note||(!eligible.includes(c)?c.synthetic?'Synthetic practice':reviewErrors(c).join('; '):'')]);const names=project.labels.map(l=>l.name);C.check(new Set(names).size===names.length&&!names.includes('background'),'Label names must be unique and cannot be background');C.check(project.labels.every((l,i)=>l.value===i+1),'nnU-Net export requires consecutive label values 1,2,3… in order');files['segmentation/dataset.json']=JSON.stringify({name:project.name,channel_names:{0:eligible.every(c=>c.modality==='MR')?'MRI':'image'},labels:{background:0,...Object.fromEntries(project.labels.map(l=>[l.name,l.value]))},numTraining:trainIds.length+validationIds.length,file_ending:'.nii.gz'},null,2);files['segmentation/splits_final.json']=JSON.stringify([{train:trainIds,val:validationIds}],null,2);files['splits.json']=JSON.stringify({seed,grouped_by:'subject_group',train:trainIds,validation:validationIds,test:testIds},null,2);files['classification.csv']=csv(classification);files['tracking.csv']=csv(tracking);files['bounding_boxes.json']=JSON.stringify(boxes,null,2);files['provenance.json']=JSON.stringify(provenance,null,2);const {cases,...settings}=project;files['project_settings.json']=JSON.stringify(settings,null,2);files['README.md']=`# ${project.name}\n\nResearch annotation export.\n\n${eligible.length} reviewed cases. Train ${trainIds.length}, validation ${validationIds.length}, test ${testIds.length}. Seed ${seed}.\n\nImages and masks have matching geometry. Masks are uint16; 0 is background. Bounding boxes use voxel IJK coordinates with inclusive upper bounds. Landmarks use LPS millimetres.\n\nFor nnU-Net, place segmentation in nnUNet_raw/Dataset001_Custom (choose your dataset ID), preprocess, then copy splits_final.json into the corresponding preprocessed dataset folder before training fold 0. Test labels in labelsTs are held out and must never be used for training. Empty splits require a larger dataset or adjusted ratios.\n\nMultiple sequences are exported as separate single-channel cases, not registered multichannel volumes. Keep related series under one subject group. Review acquisition and label consistency before pooling different modalities.\n\nAI suggestions and image-processing proposals are not automatically ground truth. Review, calibration and independent agreement checks remain required by your protocol.\n`;
download(C.zip(files),'MedAnnotate-training-dataset.zip');$('dialog').close();message(`Exported ${eligible.length} reviewed cases: ${trainIds.length} train / ${validationIds.length} validation / ${testIds.length} test.`)})});
async function gzip(bytes){return new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer())}
let managedSliceModel=false;
bind('model',()=>{C.check(current(),'Open a case first');const managed=managedSliceModel;managedSliceModel=false;modal(`<h2>${managed?'Local AI suggestion':'Connect a segmentation model'}</h2><p>${managed?'The installed trained model runs on this computer. Draw a tight box around the structure you want to segment.':'Connect a trusted model server, or use Set up local AI automatically for managed installation.'}</p><label ${managed?'hidden':''}>HTTPS endpoint (localhost HTTP is also allowed)<input id="modelURL" placeholder="https://your-server.example/segment"></label><label>Box: x0,y0,x1,y1 in displayed slice pixels<input id="modelBox" placeholder="20,20,100,100" value="${promptBox?.axis===axis&&promptBox?.k===k?promptBox.box.join(','):''}"></label><label ${managed?'hidden':''}>API token (optional, kept only for this request)<input id="modelKey" type="password" autocomplete="off"></label><p class="hint">This sends the current windowed slice, seed label, and dimensions. The service must allow this app’s origin through CORS. Remote connections need HTTPS.</p><label class="check"><input type="checkbox" id="modelConsent">I approve sending this slice to this endpoint and checked it for identifying information.</label><button id="callModel" class="primary wide">Request mask suggestion</button>`);bind('callModel',async()=>{C.check($('modelConsent').checked,'Confirm before transmitting an image');const url=new URL(managed?'http://127.0.0.1':$('modelURL').value);C.check(url.protocol==='https:'||(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)),'Use HTTPS or a loopback HTTP model server');const c=current(),modelLabels=JSON.stringify(project.labels),caseRevision=c.annotationRevision||0,caseData=c.data,caseIndex=active,p=C.plane(c.dims,axis,k),callAxis=axis,callK=k,callLabel=label,canvas=document.createElement('canvas');canvas.width=p.w;canvas.height=p.h;const cc=canvas.getContext('2d'),im=cc.createImageData(p.w,p.h),win=Math.max(.01,+$('window').value),lev=+$('level').value;for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++){let g=Math.max(0,Math.min(255,(c.data[p.index(x,y)]-lev+win/2)*255/win));if(c.inverse)g=255-g;const o=(x+y*p.w)*4;im.data[o]=im.data[o+1]=im.data[o+2]=g;im.data[o+3]=255}cc.putImageData(im,0,0);const box=$('modelBox').value.split(',').map(Number);C.check(box.length===4&&box.every(Number.isFinite)&&box[0]>=0&&box[1]>=0&&box[0]<box[2]&&box[1]<box[3]&&box[2]<=p.w&&box[3]<=p.h,'Enter a valid box around the target in slice pixels');const token=$('modelKey').value;$('callModel').disabled=true;try{const payload={image:canvas.toDataURL('image/png').split(',')[1],width:p.w,height:p.h,box,label:callLabel,axis:callAxis,slice:callK,consent:true};const response=managed?null:await fetch(url.href,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(payload),redirect:'error',signal:AbortSignal.timeout(600000)});if(response)C.check(response.ok,'Model server returned HTTP '+response.status);const result=managed?await localAICall('infer',payload):await response.json();C.check(result.width===p.w&&result.height===p.h&&Array.isArray(result.mask)&&result.mask.length===p.w*p.h&&result.mask.every(x=>x===0||x===1),'Expected matching width/height and flat binary mask array');C.check(current()===c&&active===caseIndex&&c.data===caseData&&(c.annotationRevision||0)===caseRevision&&JSON.stringify(project.labels)===modelLabels,'Case changed while model was running');C.check(c.synthetic||c.privacy?.state==='approved','Privacy clearance changed while model was running');axis=callAxis;k=callK;label=callLabel;$('axis').value=axis;const indices=[];result.mask.forEach((v,i)=>{if(v)indices.push(p.index(i%p.w,Math.floor(i/p.w)))});suggest(indices,'Connected model: '+(String(result.model||url.hostname).slice(0,120)));$('dialog').close()}finally{$('modelKey').value='';$('callModel').disabled=false}})});
bind('drive',()=>{modal(`<h2>Images from Google Drive</h2><p><b>Simple option:</b> use Google Drive for desktop and choose its synced DICOM folder, or download your images from Drive and import them.</p><button id="driveLocal" class="wide">Choose a synced Drive folder</button><hr><p><b>Direct cloud import:</b> requires your own Google OAuth web client ID with this app’s origin authorized. Access is read-only; imported pixels stay on this computer.</p><label>Google OAuth client ID<input id="clientID" placeholder="…apps.googleusercontent.com" value="${esc(driveClient)}"></label><label>Drive folder ID (optional)<input id="driveFolder" placeholder="Folder ID from your Drive URL"></label><button id="signDrive" class="primary wide">Connect Google Drive</button><div id="driveList"></div>`);bind('driveLocal',()=>{$('dialog').close();$('folders').click()});bind('signDrive',async()=>{C.check(location.protocol!=='file:','Direct Google sign-in is available in the web/localhost version. In the desktop app, use a synced Drive folder.');driveClient=$('clientID').value.trim();C.check(driveClient.endsWith('.apps.googleusercontent.com'),'Enter a valid Google OAuth web client ID');if(!window.google?.accounts){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.onload=resolve;s.onerror=()=>reject(Error('Could not load Google sign-in. Use a downloaded or synced Drive folder.'));document.head.append(s)})}google.accounts.oauth2.initTokenClient({client_id:driveClient,scope:'https://www.googleapis.com/auth/drive.readonly',callback:safe(async res=>{C.check(!res.error,res.error_description||res.error);driveToken=res.access_token;await listDrive()}),error_callback:()=>message('Google sign-in closed or failed. Check the OAuth origin configuration.',true)}).requestAccessToken({prompt:'consent'})})});
async function listDrive(pageToken){const folder=$('driveFolder').value.trim();C.check(!folder||/^[a-zA-Z0-9_-]+$/.test(folder),'Invalid folder ID');const query="trashed = false"+(folder?` and '${folder}' in parents`:''),url=new URL('https://www.googleapis.com/drive/v3/files');url.search=new URLSearchParams({q:query,pageSize:'100',fields:'nextPageToken,files(id,name,mimeType,size)',...(pageToken?{pageToken}:{})});const response=await fetch(url,{headers:{Authorization:'Bearer '+driveToken}});C.check(response.ok,'Drive request failed ('+response.status+'). Reconnect and check permissions.');const data=await response.json();$('driveList').innerHTML=`<p>Select image files in this folder. For a series, select all its DICOM slices. Folder navigation loads one folder at a time.</p>${data.files.map((f,i)=>f.mimeType==='application/vnd.google-apps.folder'?`<button class="drive-file" data-folder="${i}">Folder · ${esc(f.name)}</button>`:`<label class="check"><input type="checkbox" data-drive="${i}">${esc(f.name)}</label>`).join('')}<button id="importDrive" class="primary wide">Import selected files</button>${data.nextPageToken?'<button id="nextDrive" class="wide">Next page (import selection first)</button>':''}<button id="disconnectDrive" class="wide">Disconnect</button>`;$('driveList').querySelectorAll('[data-folder]').forEach(b=>b.onclick=safe(async()=>{$('driveFolder').value=data.files[+b.dataset.folder].id;await listDrive()}));bind('importDrive',async()=>{const selected=[...$('driveList').querySelectorAll('[data-drive]:checked')].map(x=>data.files[+x.dataset.drive]);C.check(selected.length,'Select files to import');const files=[];for(const f of selected){C.check(!f.size||+f.size<600*1024*1024,'Drive file too large');const r=await fetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(f.id)+'?alt=media',{headers:{Authorization:'Bearer '+driveToken}});C.check(r.ok,'Could not download '+f.name);files.push(new File([await r.blob()],f.name))}await importFiles(files);$('dialog').close()});if(data.nextPageToken)bind('nextDrive',()=>listDrive(data.nextPageToken));bind('disconnectDrive',()=>{if(driveToken)google.accounts.oauth2.revoke(driveToken,()=>{});driveToken=null;$('dialog').close()})}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('dialog').open)return;if((e.ctrlKey||e.metaKey)&&['s','z','y'].includes(e.key.toLowerCase())){e.preventDefault();$(e.key.toLowerCase()==='s'?'save':e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo').click();return}if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('prev').click();const tools={b:'brush',e:'eraser',s:'grow',l:'landmark',x:'box'};if(tools[e.key])document.querySelector(`[data-tool="${tools[e.key]}"]`).click()});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('medannotate-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const saved=await new Promise((resolve,reject)=>{const tx=db.transaction('projects'),r=tx.objectStore('projects').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved){validateProject(saved);project=saved;label=project.labels[0].value;select(project.cases.length?0:-1);message('Restored your last browser workspace. Save a portable backup regularly.')}}catch(e){message('Browser autosave unavailable: '+e.message+'. Use Save project for backups.',true)}finally{restoreDone=true;renderAll()}}init();

bind('dicomExport',()=>{const c=current();C.check(c,'Open an image first');C.check(c.synthetic||c.privacy?.state==='approved','Complete Privacy intake before exporting an image');download(new Blob([MedDicomExport.write(c)],{type:'application/dicom'}),c.id+'.dcm');message('Derived DICOM downloaded. Source identifiers and annotations are excluded; image pixels are preserved as currently shown in the workspace.')});
